import{_ as o,C as r,o as n,c as s,a2 as t,E as i}from"./chunks/framework.BSaF8iZ6.js";const m=JSON.parse('{"title":"Generate Product Content","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/generate-product-content.md","filePath":"generative-ai/generate-product-content.md","lastUpdated":1789411447000}'),d={name:"generative-ai/generate-product-content.md"};function l(h,e,c,g,u,p){const a=r("ImagePopup");return n(),s("div",null,[e[0]||(e[0]=t('<h1 id="generate-product-content" tabindex="-1">Generate Product Content <a class="header-anchor" href="#generate-product-content" aria-label="Permalink to &quot;Generate Product Content&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Seller Panel</span><span>Catalog &gt;&gt; Products</span></div><p>Generative AI (Magic AI) writes a product listing from a short description. The seller checks each suggestion, applies the ones they want to the product form, and saves the product as usual.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>The admin has switched Generative AI on for sellers. See <a href="./../configuration/generative-ai">Generative AI Configuration</a>.</li><li>The product is one you created yourself. The button isn&#39;t shown for products you sell from the catalog with <strong>Sell as Yours</strong>.</li><li>If you are a team member, your role includes <strong>Generate Content With Magic AI</strong>.</li></ul><p>Create the product first with <strong>List Your Product</strong>. The button is on the product&#39;s edit page. See <a href="./../catalog/product-management">Product Management</a>.</p><h2 id="describe-the-product" tabindex="-1">Describe the product <a class="header-anchor" href="#describe-the-product" aria-label="Permalink to &quot;Describe the product&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; Products</strong>.</li><li>Click the edit arrow on the product.</li><li>Click <strong>Generate content</strong> at the top of the page.</li><li>In <strong>Describe your product</strong>, write what you sell, between 10 and 2,000 characters. The more specific you are, the better the result.</li><li>Click <strong>Generate</strong>. Writing usually takes 5 to 15 seconds.</li></ol>',8)),i(a,{src:"/images/generative-ai/describe-product.png",alt:"The Generate content dialog with a product description and the fields to fill"}),e[1]||(e[1]=t('<p>Content is written in your Seller Panel language, the <strong>Locale</strong> under <strong>Settings &gt;&gt; General</strong>. Suggestions are applied to the language shown on the edit page, so choose the same language in both places before you generate.</p><h3 id="add-reference-photos" tabindex="-1">Add reference photos <a class="header-anchor" href="#add-reference-photos" aria-label="Permalink to &quot;Add reference photos&quot;">​</a></h3><p>When the admin allows it, you can attach photos for the model to look at before you click <strong>Generate</strong>:</p><ul><li>Under <strong>Reference images</strong>, click <strong>Add images</strong> and choose JPG, PNG or WebP files up to 2 MB each. The dialog shows how many you can add.</li><li>Tick <strong>Use these images as product images.</strong> to add the photos to the product&#39;s images when you apply the suggestions.</li></ul><h3 id="choose-the-fields-to-fill" tabindex="-1">Choose the fields to fill <a class="header-anchor" href="#choose-the-fields-to-fill" aria-label="Permalink to &quot;Choose the fields to fill&quot;">​</a></h3><p>When the admin allows it, <strong>Fields to fill</strong> lists every field that can be generated, all selected at first. Click a field to leave it out, or use <strong>Select all</strong> and <strong>Clear all</strong>.</p><h2 id="review-and-apply-the-suggestions" tabindex="-1">Review and apply the suggestions <a class="header-anchor" href="#review-and-apply-the-suggestions" aria-label="Permalink to &quot;Review and apply the suggestions&quot;">​</a></h2><p>Each suggested value appears on its own card, marked <strong>new</strong> when the field was empty or <strong>replaces</strong> when it had a value, with the current value struck through.</p><ol><li>Untick any card you don&#39;t want. A <strong>Categories</strong> card appears when categories are suggested.</li><li>To get a different value for one field, click its <strong>Regenerate this field</strong> icon.</li><li>Click <strong>Apply</strong>. The button shows how many fields will be applied.</li><li>Click <strong>Close</strong>.</li></ol><p>The dialog confirms how many fields were updated. Applied fields are outlined in yellow until you change them. If the name changed, the <strong>URL Key</strong> is updated to match.</p><p>A suggestion that doesn&#39;t fit the field, such as a colour your store doesn&#39;t have, is listed as skipped with the reason.</p><h2 id="save-the-product" tabindex="-1">Save the product <a class="header-anchor" href="#save-the-product" aria-label="Permalink to &quot;Save the product&quot;">​</a></h2><p>Applying only fills in the form. Nothing is stored until you save:</p><ul><li><strong>Save as Draft</strong> or <strong>Submit</strong> for a draft product.</li><li><strong>Save Product</strong> for a product you have already submitted.</li></ul><p>Using Generative AI doesn&#39;t change the product&#39;s approval. See <a href="./../catalog/product-approval">Product Approval</a>.</p><h2 id="what-can-be-generated" tabindex="-1">What can be generated <a class="header-anchor" href="#what-can-be-generated" aria-label="Permalink to &quot;What can be generated&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Generated</th><th>Never generated</th></tr></thead><tbody><tr><td>Name, short description and description</td><td>Images and files</td></tr><tr><td>Meta title, meta keywords and meta description</td><td>Yes/No switches, such as Status or Featured</td></tr><tr><td>Price, cost, special price and its dates</td><td>SKU, URL key and product number</td></tr><tr><td>Length, width, height and weight</td><td>Tax category, RMA rule and barcode value</td></tr><tr><td>Options such as colour, size and brand</td><td></td></tr><tr><td>Categories</td><td></td></tr></tbody></table><p>The admin can narrow this list further. Depending on the settings, fields you have already filled may be left out too.</p><h2 id="when-the-button-can-t-generate" tabindex="-1">When the button can&#39;t generate <a class="header-anchor" href="#when-the-button-can-t-generate" aria-label="Permalink to &quot;When the button can&#39;t generate&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>What it means</th></tr></thead><tbody><tr><td><strong>You have used all … generations for this period</strong></td><td>Your limit is used up. The dialog says when it resets. Ask the store admin if you need more.</td></tr><tr><td><strong>Generation unavailable</strong></td><td>Generative AI is switched off for the store or for your shop.</td></tr><tr><td><strong>Nothing left to fill</strong></td><td>Every field that can be generated already has a value. Clear a field, or ask the admin to allow overwriting.</td></tr><tr><td><strong>Couldn&#39;t generate content just now</strong></td><td>The AI service didn&#39;t respond. Click <strong>Try again</strong>. The failed attempt doesn&#39;t count towards your limit.</td></tr></tbody></table><p>Each <strong>Generate</strong> and each <strong>Regenerate this field</strong> uses one generation. See <a href="./usage-limits">Usage Limits</a>.</p>',21))])}const b=o(d,[["render",l]]);export{m as __pageData,b as default};
